import AbstractPollListState, { pollListEmitter } from './AbstractPollListState';
const DELETED = 'pollgroup.deleted';
export default class PollGroupListState extends AbstractPollListState {
  static notifyDeleted(pollGroup) {
    pollListEmitter.emit(DELETED, pollGroup);
  }
  get type() {
    return 'poll_groups';
  }
  deletedEvent() {
    return DELETED;
  }
  defaultSort() {
    return 'newest';
  }
  includes() {
    return ['polls'];
  }
  sortMap() {
    const map = {};
    if (this.params.q) map.relevance = '';
    map.newest = '-createdAt';
    map.oldest = 'createdAt';
    return map;
  }
}
flarum.reg.add('fof-polls', 'forum/states/PollGroupListState', PollGroupListState);